contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public entry: try to withdraw and assert recorded balance decreased by amount on success
    function run(uint256 amount) public payable {
        // No precondition on amount; we will observe whether withdraw reverts.
        // Read recorded balance before attempting withdraw via the public getter for balances (generated for mapping if accessible).
        // The mapping is not public in C, so we cannot call c.balances(address). Instead observe by attempting withdraw and then using behavior: C has no getter for balances, so instead use refund path to learn change.
        // However the constraint forbids reading non-public. To observe the caller's recorded balance, we can rely on withdraw's require and effects: we will first attempt withdraw; if it succeeds then a subsequent withdraw of 1 must revert when original balance was exactly amount (but that is complex). Simpler: call withdraw(amount) and then call refund() to read effects via contract balances (address(c).balance) and ensure recorded balance decreased by amount by checking that contract's balance decreased by at least amount and that withdraw did not revert implies recorded balance decreased by amount per specification.

        // To make an observable check that depends only on public surface, record contract balance before and after.
        uint256 beforeContractBal = address(c).balance;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterContractBal = address(c).balance;

        // General rule: if withdraw succeeded, then the contract's Ether balance decreased by at least amount
        // and (per the contract's intended invariant) the caller's recorded balance decreased by exactly amount.
        // We can state the rule referencing only public observations and the revert flag: if not reverted then afterContractBal <= beforeContractBal && beforeContractBal - afterContractBal >= amount.
        // Use <= and >= to avoid underflow in assert.
        assert(reverted || (afterContractBal <= beforeContractBal && (beforeContractBal - afterContractBal) >= amount));
    }

    // allow receiving Ether so this test can hold and forward funds if needed
    receive() external payable {}
}

